@id: textprocessor.deprocess.labelprovider.text
@description: Wrap ILabelProvider.getText() calls with TextProcessor.deprocess() to remove BiDi markers. This is useful for preventing BiDi markers from appearing in copied text.
@severity: HINT
*/
